from pathlib import Path
import json
from html import escape

ROOT=Path(__file__).resolve().parent
def write(path,content):
 p=ROOT/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content,encoding='utf-8')

icon='<svg viewBox="0 0 32 32" fill="none" aria-hidden="true"><path d="m8 10 8-5 8 5-8 5-8-5Zm0 7 8 5 8-5M8 24l8 5 8-5" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg>'
arrow='<span aria-hidden="true">↗</span>'
